-- ========================================================================================
-- Ticket 111269 · tipo 1259: cambios de notificaciones BuildType = 1
-- Archivo     : 111269_tipo1259.sql
-- Tipo        : 1259 - Request Not Completed! Technical Issues
-- Componentes : (ninguno)
-- Idiomas nuevos: Francés (4) a partir de inglés (2)
-- Fecha       : 2026-10-23
-- Autor       : Autora de ejemplo
-- Deshacer    : deshacer_111269_tipo1259.sql
-- Generado por EditorNotificaciones. Idempotente: correrlo dos veces deja la BD igual.
-- Cambios:
--   1. Tipo 1259, idioma 1: disclaimer superior #3 → #9 (NotificationTemplateLang.DisclaimerTopID).
--   2. Tipo 1259, idioma 2: disclaimer superior #4 → #10 (NotificationTemplateLang.DisclaimerTopID).
--   3. Tipo 1259, idioma nuevo Francés (4): sección propia %ContentBody_0% (interna 1) → INSERT SectionContent (ID por SCOPE_IDENTITY).
--   4. Tipo 1259, idioma nuevo Francés (4): INSERT NotificationTemplateLang (plantilla 1, estilo 2, disclaimers #11 / #12, asunto "Demande de signature électronique non complétée (exemple)").
--   5. Tipo 1259, idioma nuevo Francés (4): INSERT NotificationSectionContent × 3 (ContentBody_0 → propia, ContentBottom_0 → compartida #75, ContentHeader_0 → compartida #74).
-- ADVERTENCIA: Idioma forzado: hoy el tipo 1259 no tiene francés y CSGetCustomerNotificationHistory fuerza todos sus envíos a Lang_Id = 2 (inglés). Al agregar francés la regla deja de aplicar: los envíos con Lang_Id = 1 dejarán de forzarse a inglés y saldrán en español, los de Lang_Id = 2 en inglés y los de Lang_Id = 4 en francés. Revisa con quien genera los envíos qué Lang_Id manda hoy.
-- ========================================================================================
USE [Masterdb];
SET NOCOUNT ON;
SET XACT_ABORT ON;

-- Valores (base = lo que había al tomar el borrador; nuevo = lo que deja este cambio).
DECLARE @C1_Base INT = 3, @C1_Nuevo INT = 9;
DECLARE @C2_Base INT = 4, @C2_Nuevo INT = 10;
-- Idiomas nuevos (los IDs IDENTITY nuevos se capturan con SCOPE_IDENTITY o se ubican por llave natural).
-- Francés (4)
DECLARE @L4_Subject VARCHAR(MAX) = 'Demande de signature électronique non complétée (exemple)';
DECLARE @L4_StyleSection VARCHAR(MAX) = '<style>.notificacion .notificacion-cuerpo p {mso-hyphenate: none; text-align: justify;} h2{mso-hyphenate: none;}</style>';
DECLARE @L4_Title VARCHAR(MAX) = NULL;
DECLARE @L4_DSup_Id INT = 11;
DECLARE @L4_DInf_Id INT = 12;
DECLARE @L4_S1_Id INT;  -- ContentBody_0 propia
DECLARE @L4_S1_Nuevo VARCHAR(MAX) = '<td class="notificacion-cuerpo"><h2>Demande non complétée ! Problèmes techniques</h2><p>Bonjour %ContactFirstName% %ContactLastName%, texte d’exemple pour le tutoriel.</p></td>';
DECLARE @L4_S3_Id INT = 75;  -- ContentBottom_0 compartida
DECLARE @L4_S4_Id INT = 74;  -- ContentHeader_0 compartida

/* -------------------------------------------------------------------------------------
   Precondiciones (sin transacción abierta): si una falla, THROW y no se escribe nada.
   Cada valor se compara en binario (HASHBYTES SHA2_256): la collation CI no distingue mayúsculas.
   ------------------------------------------------------------------------------------- */
IF NOT EXISTS (SELECT 1 FROM dbo.NotificationTypes WHERE NotificationTypeID = 1259 AND BuildType = 1)
    THROW 50001, N'El tipo 1259 no existe o no es BuildType = 1.', 1;
IF (SELECT COUNT(*) FROM dbo.NotificationTemplateLang WHERE NotificationTypeID = 1259 AND Lang_id = 1) <> 1
    THROW 50002, N'NotificationTemplateLang tipo 1259 idioma 1: debe haber exactamente una fila.', 1;
IF NOT EXISTS (SELECT 1 FROM dbo.NotificationTemplateLang l
               INNER JOIN dbo.NotificationTemplateContent c ON c.ContentID = l.ContentID
               INNER JOIN dbo.NotificationTemplateStyles s ON s.StyleID = l.BaseStyle
               WHERE l.NotificationTypeID = 1259 AND l.Lang_id = 1)
    THROW 50003, N'NotificationTemplateLang tipo 1259 idioma 1: la plantilla (ContentID) o el estilo base (BaseStyle) no existe.', 1;
IF (SELECT COUNT(*) FROM dbo.NotificationTemplateLang WHERE NotificationTypeID = 1259 AND Lang_id = 2) <> 1
    THROW 50004, N'NotificationTemplateLang tipo 1259 idioma 2: debe haber exactamente una fila.', 1;
IF NOT EXISTS (SELECT 1 FROM dbo.NotificationTemplateLang l
               INNER JOIN dbo.NotificationTemplateContent c ON c.ContentID = l.ContentID
               INNER JOIN dbo.NotificationTemplateStyles s ON s.StyleID = l.BaseStyle
               WHERE l.NotificationTypeID = 1259 AND l.Lang_id = 2)
    THROW 50005, N'NotificationTemplateLang tipo 1259 idioma 2: la plantilla (ContentID) o el estilo base (BaseStyle) no existe.', 1;
-- 1. Tipo 1259, idioma 1: disclaimer superior #3 → #9 (NotificationTemplateLang.DisclaimerTopID).
IF NOT EXISTS (SELECT 1 FROM dbo.NotificationTemplateLang WHERE NotificationTypeID = 1259 AND Lang_id = 1 AND DisclaimerTopID IN (@C1_Base, @C1_Nuevo))
    THROW 50006, N'NotificationTemplateLang tipo 1259 idioma 1: DisclaimerTopID no es ni el que se tomó para el borrador ni el nuevo (alguien lo cambió).', 1;
IF NOT EXISTS (SELECT 1 FROM dbo.NotificationTemplateDisclaimer WHERE DisclaimerID = @C1_Nuevo)
    THROW 50007, N'El disclaimer 9 que se vincula no existe.', 1;
-- 2. Tipo 1259, idioma 2: disclaimer superior #4 → #10 (NotificationTemplateLang.DisclaimerTopID).
IF NOT EXISTS (SELECT 1 FROM dbo.NotificationTemplateLang WHERE NotificationTypeID = 1259 AND Lang_id = 2 AND DisclaimerTopID IN (@C2_Base, @C2_Nuevo))
    THROW 50008, N'NotificationTemplateLang tipo 1259 idioma 2: DisclaimerTopID no es ni el que se tomó para el borrador ni el nuevo (alguien lo cambió).', 1;
IF NOT EXISTS (SELECT 1 FROM dbo.NotificationTemplateDisclaimer WHERE DisclaimerID = @C2_Nuevo)
    THROW 50009, N'El disclaimer 10 que se vincula no existe.', 1;
-- Idiomas nuevos: Francés (4).
-- Catálogo: lo que se vincula por ID debe existir (plantilla, estilo, disclaimers, secciones compartidas y secciones de la plantilla).
IF NOT EXISTS (SELECT 1 FROM dbo.NotificationTemplateContent WHERE ContentID = 1)
    THROW 50010, N'La plantilla ContentID 1 no existe.', 1;
IF NOT EXISTS (SELECT 1 FROM dbo.NotificationTemplateStyles WHERE StyleID = 2)
    THROW 50011, N'El estilo base StyleID 2 no existe.', 1;
IF NOT EXISTS (SELECT 1 FROM dbo.NotificationTemplateDisclaimer WHERE DisclaimerID = @L4_DSup_Id AND Lang_id = 4 AND IsTop = 1)
    THROW 50012, N'El disclaimer superior 11 del idioma 4 no existe (o es de otro idioma o posición).', 1;
IF NOT EXISTS (SELECT 1 FROM dbo.NotificationTemplateDisclaimer WHERE DisclaimerID = @L4_DInf_Id AND Lang_id = 4 AND IsTop = 0)
    THROW 50013, N'El disclaimer inferior 12 del idioma 4 no existe (o es de otro idioma o posición).', 1;
IF NOT EXISTS (SELECT 1 FROM dbo.RelTemplateContentSection WHERE ContentID = 1 AND InternalSectionID = 1)
    THROW 50014, N'La sección interna 1 no es de la plantilla 1 (RelTemplateContentSection).', 1;
IF NOT EXISTS (SELECT 1 FROM dbo.SectionContent WHERE SectionContentID = @L4_S3_Id AND Languaje = 4)
    THROW 50015, N'La sección compartida SectionContent 75 del idioma 4 no existe (o es de otro idioma).', 1;
IF NOT EXISTS (SELECT 1 FROM dbo.RelTemplateContentSection WHERE ContentID = 1 AND InternalSectionID = 3)
    THROW 50016, N'La sección interna 3 no es de la plantilla 1 (RelTemplateContentSection).', 1;
IF NOT EXISTS (SELECT 1 FROM dbo.SectionContent WHERE SectionContentID = @L4_S4_Id AND Languaje = 4)
    THROW 50017, N'La sección compartida SectionContent 74 del idioma 4 no existe (o es de otro idioma).', 1;
IF NOT EXISTS (SELECT 1 FROM dbo.RelTemplateContentSection WHERE ContentID = 1 AND InternalSectionID = 4)
    THROW 50018, N'La sección interna 4 no es de la plantilla 1 (RelTemplateContentSection).', 1;
-- Idiomas nuevos (Francés (4)): su fila NotificationTemplateLang no existe o es exactamente la que deja el cambio; igual sus vínculos.
IF EXISTS (SELECT 1 FROM dbo.NotificationTemplateLang l WHERE l.NotificationTypeID = 1259 AND l.Lang_id IN (4)
           AND CASE WHEN (l.NotificationTypeID = 1259 AND l.Lang_id = 4 AND l.ContentID = 1 AND l.BaseStyle = 2 AND l.Inactive = 0 AND DATALENGTH(l.Attachement) = 0 AND ((l.[Subject] IS NULL AND @L4_Subject IS NULL) OR HASHBYTES('SHA2_256', CAST(l.[Subject] AS VARCHAR(MAX))) = HASHBYTES('SHA2_256', CAST(@L4_Subject AS VARCHAR(MAX)))) AND ((l.StyleSection IS NULL AND @L4_StyleSection IS NULL) OR HASHBYTES('SHA2_256', CAST(l.StyleSection AS VARCHAR(MAX))) = HASHBYTES('SHA2_256', CAST(@L4_StyleSection AS VARCHAR(MAX)))) AND ((l.title IS NULL AND @L4_Title IS NULL) OR HASHBYTES('SHA2_256', CAST(l.title AS VARCHAR(MAX))) = HASHBYTES('SHA2_256', CAST(@L4_Title AS VARCHAR(MAX)))) AND l.DisclaimerTopID = @L4_DSup_Id AND l.DisclaimerBottomID = @L4_DInf_Id) THEN 1 ELSE 0 END = 0)
    THROW 50019, N'El tipo 1259 ya tiene NotificationTemplateLang de Francés (4) distinta de la que agrega este script (se agregó en Masterdb después del borrador): quita el idioma nuevo del borrador y edita el que ya existe.', 1;
IF EXISTS (SELECT 1 FROM dbo.NotificationSectionContent n INNER JOIN dbo.SectionContent sc ON sc.SectionContentID = n.SectionContentID
           WHERE n.NotificationTypeID = 1259 AND sc.Languaje IN (4)
             AND CASE WHEN (n.InternalSectionID = 1 AND sc.Languaje = 4 AND ((sc.Content IS NULL AND @L4_S1_Nuevo IS NULL) OR HASHBYTES('SHA2_256', CAST(sc.Content AS VARCHAR(MAX))) = HASHBYTES('SHA2_256', CAST(@L4_S1_Nuevo AS VARCHAR(MAX))))) OR (n.InternalSectionID = 3 AND n.SectionContentID = @L4_S3_Id) OR (n.InternalSectionID = 4 AND n.SectionContentID = @L4_S4_Id) THEN 1 ELSE 0 END = 0)
    THROW 50020, N'El tipo 1259 tiene vínculos en NotificationSectionContent a secciones de Francés (4) distintos de los que agrega este script: revísalo a mano.', 1;
IF EXISTS (SELECT 1 FROM dbo.NotificationSectionContent n INNER JOIN dbo.SectionContent sc ON sc.SectionContentID = n.SectionContentID
           WHERE n.NotificationTypeID = 1259 AND sc.Languaje IN (4) GROUP BY n.InternalSectionID, sc.Languaje HAVING COUNT(*) > 1)
    THROW 50021, N'El tipo 1259 tiene más de un vínculo para la misma sección en Francés (4) en NotificationSectionContent: revísalo a mano.', 1;

DECLARE @Rollback_Backup_Table TABLE (
     ID            INT IDENTITY(1,1)
    ,ServerName    VARCHAR(120) DEFAULT @@SERVERNAME
    ,ActionType    VARCHAR(50)
    ,TableName     VARCHAR(120)
    ,RollbackQuery NVARCHAR(MAX)
    ,AffectedID    INT
    ,LanguageID    INT
);

BEGIN TRY
    BEGIN TRANSACTION;

    -- 1. Tipo 1259, idioma 1: disclaimer superior #3 → #9 (NotificationTemplateLang.DisclaimerTopID).
    IF NOT EXISTS (SELECT 1 FROM dbo.NotificationTemplateLang WHERE NotificationTypeID = 1259 AND Lang_id = 1 AND DisclaimerTopID = @C1_Nuevo)
    BEGIN
        UPDATE dbo.NotificationTemplateLang SET DisclaimerTopID = @C1_Nuevo
        OUTPUT 'UPDATE', 'Masterdb.dbo.NotificationTemplateLang',
               'UPDATE Masterdb.dbo.NotificationTemplateLang SET DisclaimerTopID = ' + CAST(deleted.DisclaimerTopID AS VARCHAR(10)) + ' WHERE NotificationTypeID = ' + CAST(deleted.NotificationTypeID AS VARCHAR(10)) + ' AND Lang_id = ' + CAST(deleted.Lang_id AS VARCHAR(10)) + ';',
               deleted.NotificationTypeID, deleted.Lang_id
        INTO @Rollback_Backup_Table (ActionType, TableName, RollbackQuery, AffectedID, LanguageID)
        WHERE NotificationTypeID = 1259 AND Lang_id = 1 AND DisclaimerTopID = @C1_Base;
        IF @@ROWCOUNT <> 1 THROW 50022, N'NotificationTemplateLang tipo 1259 idioma 1: DisclaimerTopID no es el esperado; no se aplicó nada.', 1;
    END;

    -- 2. Tipo 1259, idioma 2: disclaimer superior #4 → #10 (NotificationTemplateLang.DisclaimerTopID).
    IF NOT EXISTS (SELECT 1 FROM dbo.NotificationTemplateLang WHERE NotificationTypeID = 1259 AND Lang_id = 2 AND DisclaimerTopID = @C2_Nuevo)
    BEGIN
        UPDATE dbo.NotificationTemplateLang SET DisclaimerTopID = @C2_Nuevo
        OUTPUT 'UPDATE', 'Masterdb.dbo.NotificationTemplateLang',
               'UPDATE Masterdb.dbo.NotificationTemplateLang SET DisclaimerTopID = ' + CAST(deleted.DisclaimerTopID AS VARCHAR(10)) + ' WHERE NotificationTypeID = ' + CAST(deleted.NotificationTypeID AS VARCHAR(10)) + ' AND Lang_id = ' + CAST(deleted.Lang_id AS VARCHAR(10)) + ';',
               deleted.NotificationTypeID, deleted.Lang_id
        INTO @Rollback_Backup_Table (ActionType, TableName, RollbackQuery, AffectedID, LanguageID)
        WHERE NotificationTypeID = 1259 AND Lang_id = 2 AND DisclaimerTopID = @C2_Base;
        IF @@ROWCOUNT <> 1 THROW 50023, N'NotificationTemplateLang tipo 1259 idioma 2: DisclaimerTopID no es el esperado; no se aplicó nada.', 1;
    END;

    -- 3. Idiomas nuevos · Francés (4): SectionContent propia %ContentBody_0% (interna 1) (se reutiliza si el tipo ya la vincula)
    SET @L4_S1_Id = NULL;
    SELECT TOP (1) @L4_S1_Id = n.SectionContentID FROM dbo.NotificationSectionContent n INNER JOIN dbo.SectionContent sc ON sc.SectionContentID = n.SectionContentID WHERE n.NotificationTypeID = 1259 AND (n.InternalSectionID = 1 AND sc.Languaje = 4 AND ((sc.Content IS NULL AND @L4_S1_Nuevo IS NULL) OR HASHBYTES('SHA2_256', CAST(sc.Content AS VARCHAR(MAX))) = HASHBYTES('SHA2_256', CAST(@L4_S1_Nuevo AS VARCHAR(MAX))))) ORDER BY n.ID;
    IF @L4_S1_Id IS NULL
    BEGIN
        INSERT INTO dbo.SectionContent (Languaje, Content, Inactive)
        VALUES (4, @L4_S1_Nuevo, 0);
        SET @L4_S1_Id = SCOPE_IDENTITY();
        INSERT INTO @Rollback_Backup_Table (ActionType, TableName, RollbackQuery, AffectedID, LanguageID)
        VALUES ('INSERT', 'Masterdb.dbo.SectionContent',
                'DELETE FROM Masterdb.dbo.SectionContent WHERE SectionContentID = ' + CAST(@L4_S1_Id AS VARCHAR(10)) + ';', @L4_S1_Id, 4);
    END;

    -- 4. Idiomas nuevos · Francés (4): NotificationTemplateLang (llave: tipo + Lang_id)
    IF NOT EXISTS (SELECT 1 FROM dbo.NotificationTemplateLang WHERE NotificationTypeID = 1259 AND Lang_id = 4)
        INSERT INTO dbo.NotificationTemplateLang
            (NotificationTypeID, Lang_id, DisclaimerTopID, DisclaimerBottomID, ContentID, [Subject], Attachement, StyleSection, Inactive, title, BaseStyle)
        OUTPUT 'INSERT', 'Masterdb.dbo.NotificationTemplateLang',
               'DELETE FROM Masterdb.dbo.NotificationTemplateLang WHERE NotificationTypeID = ' + CAST(inserted.NotificationTypeID AS VARCHAR(10)) + ' AND Lang_id = ' + CAST(inserted.Lang_id AS VARCHAR(10)) + ';',
               inserted.NotificationTypeID, inserted.Lang_id
        INTO @Rollback_Backup_Table (ActionType, TableName, RollbackQuery, AffectedID, LanguageID)
        VALUES (1259, 4, @L4_DSup_Id, @L4_DInf_Id, 1, @L4_Subject, '', @L4_StyleSection, 0, @L4_Title, 2);

    -- 5. Idiomas nuevos · Francés (4): vínculo %ContentBody_0% (interna 1) → propia (llave: tipo + sección interna + idioma de la SectionContent)
    IF NOT EXISTS (SELECT 1 FROM dbo.NotificationSectionContent WHERE NotificationTypeID = 1259 AND InternalSectionID = 1 AND SectionContentID = @L4_S1_Id)
        INSERT INTO dbo.NotificationSectionContent (NotificationTypeID, InternalSectionID, SectionContentID)
        OUTPUT 'INSERT', 'Masterdb.dbo.NotificationSectionContent',
               'DELETE FROM Masterdb.dbo.NotificationSectionContent WHERE ID = ' + CAST(inserted.ID AS VARCHAR(10)) + ';',
               inserted.ID, 4
        INTO @Rollback_Backup_Table (ActionType, TableName, RollbackQuery, AffectedID, LanguageID)
        VALUES (1259, 1, @L4_S1_Id);

    -- 6. Idiomas nuevos · Francés (4): vínculo %ContentBottom_0% (interna 3) → compartida #75 (llave: tipo + sección interna + idioma de la SectionContent)
    IF NOT EXISTS (SELECT 1 FROM dbo.NotificationSectionContent WHERE NotificationTypeID = 1259 AND InternalSectionID = 3 AND SectionContentID = @L4_S3_Id)
        INSERT INTO dbo.NotificationSectionContent (NotificationTypeID, InternalSectionID, SectionContentID)
        OUTPUT 'INSERT', 'Masterdb.dbo.NotificationSectionContent',
               'DELETE FROM Masterdb.dbo.NotificationSectionContent WHERE ID = ' + CAST(inserted.ID AS VARCHAR(10)) + ';',
               inserted.ID, 4
        INTO @Rollback_Backup_Table (ActionType, TableName, RollbackQuery, AffectedID, LanguageID)
        VALUES (1259, 3, @L4_S3_Id);

    -- 7. Idiomas nuevos · Francés (4): vínculo %ContentHeader_0% (interna 4) → compartida #74 (llave: tipo + sección interna + idioma de la SectionContent)
    IF NOT EXISTS (SELECT 1 FROM dbo.NotificationSectionContent WHERE NotificationTypeID = 1259 AND InternalSectionID = 4 AND SectionContentID = @L4_S4_Id)
        INSERT INTO dbo.NotificationSectionContent (NotificationTypeID, InternalSectionID, SectionContentID)
        OUTPUT 'INSERT', 'Masterdb.dbo.NotificationSectionContent',
               'DELETE FROM Masterdb.dbo.NotificationSectionContent WHERE ID = ' + CAST(inserted.ID AS VARCHAR(10)) + ';',
               inserted.ID, 4
        INTO @Rollback_Backup_Table (ActionType, TableName, RollbackQuery, AffectedID, LanguageID)
        VALUES (1259, 4, @L4_S4_Id);

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    -- La variable de tabla sobrevive al ROLLBACK: muestra lo que se intentó antes del error.
    SELECT 'ERROR: se hizo ROLLBACK' AS Estado, * FROM @Rollback_Backup_Table ORDER BY ID;
    THROW;
END CATCH;

-- Respaldo: sentencias inversas de lo que se cambió, en el orden en que habría que correrlas.
SELECT * FROM @Rollback_Backup_Table ORDER BY ID DESC;
